// GENERATED by scripts/sync-shared.mjs from src/. Edit the source, then run `npm run shared:sync`.
// server-shared: payment webhook verification + normalisation for both providers (Web Crypto only).
// The webhook is the only thing that ever sets a subscription to active.

export type BillingProvider = 'razorpay' | 'dodo';
export type BillingStatus = 'created' | 'active' | 'halted' | 'cancelled' | 'expired';
export type Plan = 'monthly' | 'yearly';

export type BillingEvent = {
  provider: BillingProvider;
  event: string;
  /** Provider subscription id (stored as subscriptions.provider_ref). */
  ref: string;
  user_id: string | null;
  plan: Plan | null;
  status: BillingStatus;
  current_period_end: string | null;
  /** When the provider says the event happened; older events never overwrite newer state. */
  event_at: string;
};

const enc = new TextEncoder();

async function hmacSha256(key: Uint8Array, message: string): Promise<Uint8Array> {
  const k = await crypto.subtle.importKey('raw', key as BufferSource, { name: 'HMAC', hash: 'SHA-256' }, false, [
    'sign',
  ]);
  return new Uint8Array(await crypto.subtle.sign('HMAC', k, enc.encode(message) as BufferSource));
}

/** Constant-time comparison. */
export function timingSafeEqual(a: Uint8Array, b: Uint8Array): boolean {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a[i]! ^ b[i]!;
  return diff === 0;
}

const hexToBytes = (hex: string) => {
  if (!/^[0-9a-f]*$/i.test(hex) || hex.length % 2) return new Uint8Array();
  return new Uint8Array(hex.match(/../g)?.map((h) => parseInt(h, 16)) ?? []);
};
const b64ToBytes = (b64: string) => {
  try {
    return Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
  } catch {
    return new Uint8Array();
  }
};

/** Razorpay: X-Razorpay-Signature = hex(HMAC-SHA256(raw body, webhook secret)). */
export async function verifyRazorpay(rawBody: string, signature: string | null, secret: string): Promise<boolean> {
  if (!signature || !secret) return false;
  const expected = await hmacSha256(enc.encode(secret), rawBody);
  return timingSafeEqual(expected, hexToBytes(signature.trim()));
}

/**
 * Standard Webhooks (Dodo): sign "{webhook-id}.{webhook-timestamp}.{raw body}" with the base64 key after
 * "whsec_"; webhook-signature holds space-separated "v1,<base64>" entries; 5-minute replay window.
 */
export async function verifyStandardWebhook(
  rawBody: string,
  headers: { id: string | null; timestamp: string | null; signature: string | null },
  secret: string,
  nowSeconds: number = Math.floor(Date.now() / 1000),
  toleranceSeconds = 300,
): Promise<boolean> {
  const { id, timestamp, signature } = headers;
  if (!id || !timestamp || !signature || !secret) return false;
  const ts = Number(timestamp);
  if (!Number.isFinite(ts) || Math.abs(nowSeconds - ts) > toleranceSeconds) return false;
  const key = b64ToBytes(secret.startsWith('whsec_') ? secret.slice(6) : secret);
  if (!key.length) return false;
  const expected = await hmacSha256(key, `${id}.${timestamp}.${rawBody}`);
  return signature
    .split(' ')
    .map((part) => part.split(','))
    .some(([version, sig]) => version === 'v1' && !!sig && timingSafeEqual(expected, b64ToBytes(sig)));
}

const RAZORPAY_STATUS: Record<string, BillingStatus> = {
  'subscription.authenticated': 'created',
  'subscription.activated': 'active',
  'subscription.charged': 'active',
  'subscription.resumed': 'active',
  // A failed renewal being retried: keep access until Razorpay halts it.
  'subscription.pending': 'active',
  'subscription.halted': 'halted',
  'subscription.paused': 'halted',
  'subscription.cancelled': 'cancelled',
  'subscription.completed': 'expired',
};

type Json = Record<string, unknown>;
const obj = (v: unknown): Json => (v && typeof v === 'object' ? (v as Json) : {});
const str = (v: unknown): string | null => (typeof v === 'string' && v ? v : null);
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const userId = (v: unknown) => (typeof v === 'string' && UUID.test(v) ? v : null);
const planOf = (explicit: unknown, id: string | null, ids: Partial<Record<Plan, string>>): Plan | null =>
  explicit === 'monthly' || explicit === 'yearly'
    ? explicit
    : id && id === ids.yearly
      ? 'yearly'
      : id && id === ids.monthly
        ? 'monthly'
        : null;

/** Razorpay subscription.* event → normalised event, or null for events we ignore. */
export function parseRazorpay(payload: unknown, planIds: Partial<Record<Plan, string>>): BillingEvent | null {
  const p = obj(payload);
  const event = str(p.event);
  const status = event ? RAZORPAY_STATUS[event] : undefined;
  const sub = obj(obj(obj(p.payload).subscription).entity);
  const ref = str(sub.id);
  if (!event || !status || !ref) return null;
  const notes = obj(sub.notes);
  const end = typeof sub.current_end === 'number' ? new Date(sub.current_end * 1000).toISOString() : null;
  const created =
    typeof p.created_at === 'number' ? new Date(p.created_at * 1000).toISOString() : new Date().toISOString();
  return {
    provider: 'razorpay',
    event,
    ref,
    user_id: userId(notes.user_id),
    plan: planOf(notes.plan, str(sub.plan_id), planIds),
    status,
    current_period_end: end,
    event_at: created,
  };
}

const DODO_STATUS: Record<string, BillingStatus> = {
  'subscription.active': 'active',
  'subscription.renewed': 'active',
  'subscription.plan_changed': 'active',
  'subscription.on_hold': 'halted',
  'subscription.past_due': 'halted',
  'subscription.cancelled': 'cancelled',
  'subscription.failed': 'expired',
  'subscription.expired': 'expired',
};

/** Dodo (Standard Webhooks envelope: { type, timestamp, data }) → normalised event, or null. */
export function parseDodo(payload: unknown, productIds: Partial<Record<Plan, string>>): BillingEvent | null {
  const p = obj(payload);
  const event = str(p.type);
  const data = obj(p.data);
  let status = event ? DODO_STATUS[event] : undefined;
  // subscription.updated carries the new state in data.status.
  if (event === 'subscription.updated') {
    const s = str(data.status);
    status =
      s === 'active'
        ? 'active'
        : s === 'on_hold'
          ? 'halted'
          : s === 'cancelled'
            ? 'cancelled'
            : s === 'expired' || s === 'failed'
              ? 'expired'
              : undefined;
  }
  const ref = str(data.subscription_id);
  if (!event || !status || !ref) return null;
  const metadata = obj(data.metadata);
  return {
    provider: 'dodo',
    event,
    ref,
    user_id: userId(metadata.user_id),
    plan: planOf(metadata.plan, str(data.product_id), productIds),
    status,
    current_period_end: str(data.next_billing_date),
    event_at: str(p.timestamp) ?? new Date().toISOString(),
  };
}

/** Out-of-order delivery: skip an event older than the state we already stored. */
export function isStale(event: BillingEvent, storedUpdatedAt: string | null | undefined): boolean {
  return !!storedUpdatedAt && Date.parse(event.event_at) < Date.parse(storedUpdatedAt);
}
